BrokerService broker = new BrokerService();
broker.addConnector("vm://embedded-broker");
broker.setPersistent(false);
broker.start();

ConnectionFactory factory = new ActiveMQConnectionFactory("vm://embedded-broker");
Connection connection = factory.createConnection();
connection.start();
Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);

Queue kolejka = session.createQueue("zamowienia.kolejka");
MessageProducer producer = session.createProducer(kolejka);
producer.send(session.createTextMessage("Zamowienie Z100 zlozone"));

MessageConsumer consumer = session.createConsumer(kolejka);
TextMessage odebrana = (TextMessage) consumer.receive(2000); // timeout 2000ms
System.out.println(odebrana.getText()); // "Zamowienie Z100 zlozone"

Topic temat = session.createTopic("powiadomienia.temat");
MessageProducer producer = session.createProducer(temat);
producer.send(session.createTextMessage("Nowosc!"));

MessageConsumer sub = session.createConsumer(temat); // za pozno!
TextMessage odebrana = (TextMessage) sub.receive(2000); // null - timeout

